//! C entry point generated by fast-anything: JSON array of arguments in, {"ok": result} or
//! {"error": message} out. Don't edit this file; the port lives in src/port.rs.

mod port;

use serde_json::{Value, json};

fn arg<T: serde::de::DeserializeOwned>(args: &[Value], i: usize, default: Option<&str>) -> Result<T, String> {
    match args.get(i) {
        Some(v) => T::deserialize(v).map_err(|e| format!("argument {}: {e}", i + 1)),
        None => match default {
            Some(d) => serde_json::from_str(d).map_err(|e| e.to_string()),
            None => Err(format!("missing argument {}", i + 1)),
        },
    }
}

fn call(input: &[u8]) -> Result<Value, String> {
    let args: Vec<Value> = serde_json::from_slice(input).map_err(|e| e.to_string())?;
    let result = port::PsyTwbFnTdbWPbBatch(arg(&args, 0, None)?, arg(&args, 1, None)?, arg(&args, 2, None)?)?;
    serde_json::to_value(result).map_err(|e| e.to_string())
}

/// # Safety
/// input must point to len readable bytes and out_len to a writable usize.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fa_call(input: *const u8, len: usize, out_len: *mut usize) -> *mut u8 {
    let input = unsafe { std::slice::from_raw_parts(input, len) };
    let reply = match std::panic::catch_unwind(|| call(input)) {
        Ok(Ok(value)) => json!({ "ok": value }),
        Ok(Err(message)) => json!({ "error": message }),
        Err(panic) => {
            let text = panic.downcast_ref::<&str>().map(|s| s.to_string()).or_else(|| panic.downcast_ref::<String>().cloned());
            json!({ "error": format!("panic: {}", text.unwrap_or_default()) })
        }
    };
    let bytes = serde_json::to_vec(&reply).unwrap_or_default().into_boxed_slice();
    unsafe { *out_len = bytes.len() };
    Box::into_raw(bytes) as *mut u8
}

/// # Safety
/// ptr and len must come from fa_call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fa_free(ptr: *mut u8, len: usize) {
    if !ptr.is_null() {
        drop(unsafe { Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr, len)) });
    }
}

